<div class="row mb-4"><div class="col-xl-8"><div class="panel-card"><h2 class="h5 fw-bold">Passkeys</h2><p class="text-muted">Sign in securely with your fingerprint, face, device PIN, or security key.</p><div class="input-group mb-3"><input id="passkeyName" class="form-control" maxlength="80" placeholder="Passkey name, e.g. My phone"><button type="button" class="btn btn-primary" id="addPasskey"><i class="fas fa-fingerprint me-2"></i>Add passkey</button></div><div id="passkeyMessage" class="small mb-3 d-none"></div>
@forelse($user->passkeys as $passkey)<div class="border rounded p-3 mb-2 d-flex justify-content-between align-items-center gap-3"><div><strong>{{ $passkey->name }}</strong><div class="small text-muted">Added {{ $passkey->created_at->diffForHumans() }}@if($passkey->last_used_at) · Last used {{ $passkey->last_used_at->diffForHumans() }}@endif</div></div><button type="button" class="btn btn-sm btn-outline-danger remove-passkey" data-url="{{ route('customer.profile.passkeys.destroy',$passkey) }}">Remove</button></div>@empty<div class="text-muted small">No passkeys registered yet.</div>@endforelse
</div></div></div>
@push('scripts')
<script>document.addEventListener('DOMContentLoaded',()=>{const add=document.getElementById('addPasskey'),name=document.getElementById('passkeyName'),message=document.getElementById('passkeyMessage'),show=(text,bad=false)=>{message.textContent=text;message.className='small mb-3 '+(bad?'text-danger':'text-success')};if(!window.Passkeys.isSupported()){add.disabled=true;show('Passkeys are not supported by this browser.',true)}add.addEventListener('click',async()=>{if(!name.value.trim()){show('Enter a name for this passkey.',true);return}add.disabled=true;try{await window.Passkeys.register({name:name.value.trim(),routes:{options:@json(route('customer.profile.passkeys.options')),submit:@json(route('customer.profile.passkeys.store'))}});window.location.reload()}catch(e){show(e.message||'Could not add passkey.',true);add.disabled=false}});document.querySelectorAll('.remove-passkey').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Remove this passkey?'))return;const password=@json($user->google_id ? '' : null)??prompt('Enter your current password');if(password===null)return;button.disabled=true;const response=await fetch(button.dataset.url,{method:'DELETE',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({password})});if(response.ok){window.location.reload()}else{const data=await response.json();show(data.message||'Could not remove passkey.',true);button.disabled=false}}))});</script>
@endpush
